            KEYSPACE_WORKFLOW_SOURCE,
            KEYSPACE_COMPILED_IR,
            KEYSPACE_RUN_HEADER,
            KEYSPACE_RUN_EVENT,
            KEYSPACE_RUN_SNAPSHOT,
            KEYSPACE_BLOB,
            KEYSPACE_INDEX_STATUS,
            KEYSPACE_INDEX_WORKFLOW,
            KEYSPACE_INDEX_ACTION,
            KEYSPACE_RUN_INPUTS,
            KEYSPACE_EMERGENCY_DENY,
            KEYSPACE_ARTIFACT_ACCEPTANCE,
        ]
    }

